from pathlib import Path
import html,json
b=Path(__file__).resolve().parents[1];e=lambda x:html.escape(str(x))
o=json.loads((b/'data/round19_image_BC_observations.json').read_text())
s='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Цикл19 · графика без чтения</title><style>body{max-width:1250px;margin:auto;padding:28px;font:18px/1.6 system-ui;color:#202c37;background:#f3f0e7}a{color:#165479}.note{background:#e7dfcd;padding:20px;border-left:4px solid #776341}.views{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:22px}figure{margin:0;background:white;padding:18px;border:1px solid #ccc}figure img{width:100%;height:auto}.tokens{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:18px;margin-top:24px}.tokens img{width:auto;max-width:100%;image-rendering:auto}.tokens figcaption{font-size:16px}small{display:block}</style><h1>Графика без назначенных звуков</h1><p>Цикл19 ·25 октября2026</p><p class="note">Три новых снимка разобраны без раскрытия индивидуальных чтений и переводов. Прежние знания остаются известны: полной слепоты не заявляется. На C выбраны девять комплексов и шесть предварительных графических классов. Это ещё не алфавит и не расшифровка.</p><p><a href="observations/2026-10-25_round19_return_to_images.txt">Отчёт</a> · <a href="RESEARCH_METHOD.txt">Уточнённый метод</a> · <a href="data/round19_crop_review.json">Уточнение по фрагментам</a></p><div class="views">'''
for label,caption in [('A','Сильное повреждение; надёжные границы знаков не получены.'),('B','Борозды и углубления видны, но полный набор комплексов уверенно не выделяется.'),('C','Верхний вид: полосы и ячейки с различающимися конфигурациями. Направление чтения и функции форм не установлены.')]:
 s+=f'<figure><a href="sources/round19_image_{label}.jpg"><img src="sources/round19_image_{label}.jpg" alt="Снимок {label}"></a><figcaption>Снимок {label}. {caption} Современные инвентарные надписи исключены из анализа.</figcaption></figure>'
s+='</div><h2>Девять выбранных комплексов C</h2><p>Группы обозначают только визуальное сходство. Внутренние детали круглых форм сохранены как различия. Фрагменты показаны в исходном пиксельном размере.</p><div class="tokens">'
for r in o['tokens']:
 desc=r['description']
 if r['token'] in ['C04','C05']:desc='Вертикальный штрих с одним ясным ответвлением вправо. Верхний горизонтальный участок может быть границей ячейки; исходное предположение о двух ответвлениях уточнено.'
 s+='<figure><img src="'+e(r['crop_file'])+'" alt="'+e(r['token'])+'"><figcaption><b>'+e(r['token'])+' · '+e(r['provisional_graphic_group'])+'</b><small>'+e(desc)+'</small><small>Звук: не назначен. Значение: не назначено.</small></figcaption></figure>'
s+='</div><p>Ячейка не принята автоматически за слово; комплекс может состоять из более мелких единиц. Датировка и языковая атрибуция выбранных предметов в этом первичном этапе не проверялись. Предметные редакции не раскрывались автоматически после фиксации наблюдений. Происхождение сохранено отдельно в реестре источников.</p></html>'
(b/'comparison_round19.html').write_text(s)
print('Neutral viewer built.')
